local extraCodes = {"fr", "de", "tr", "pl"}
for _, code in ipairs(extraCodes) do translations[code] = {} end
for _, row in ipairs(extraRows) do
    assert(translations.en[row[1]], "Unknown translation key: " .. row[1])
    for i, code in ipairs(extraCodes) do
        translations[code][row[1]] = assert(row[i+1], "Missing translation: " .. row[1] .. " / " .. code)
    end
end
for _, language in ipairs(I18n.languages) do
    for key in pairs(translations.en) do
        assert(translations[language.code][key], "Missing translation: " .. key .. " / " .. language.code)
    end
end
I18n.translations = translations
function I18n.setLanguage(code)
    I18n.language = translations[code] and code or "en"
    return I18n.language
end
function I18n.t(key, ...)
    local value = translations[I18n.language][key] or key
    if select("#", ...) > 0 then return string.format(value, ...) end
    return value
end
return I18n
